		});
	};

	Messaging.renameRoom = async function (uid, roomId, newName) {
		newName = String(newName).trim();
		checkRoomName(newName);

		const payload = await plugins.hooks.fire('filter:chat.renameRoom', {
			uid: uid,
			roomId: roomId,
			newName: newName,
		});
