			throw new Error('[[error:no-room]]');
		}
		if (data.toMid) {
			if (!await Messaging.messageExists(data.toMid)) {
				throw new Error('[[error:invalid-mid]]');
			}
			if (!await Messaging.canViewMessage(data.toMid, roomId, uid)) {
				throw new Error('[[error:no-privileges]]');
