'use strict';

const db = require('../../database');
const batch = require('../../batch');

module.exports = {
	name: 'Migrate restricted chats to chat allow lists',
	timestamp: Date.UTC(2025, 3, 16),
	method: async function () {
		const { progress } = this;
		const defaultRestrictChat = await db.getObjectField('config', 'restrictChat');

		await batch.processSortedSet('users:joindate', async (uids) => {
			const settings = await db.getObjects(uids.map(uid => `user:${uid}:settings`));
			const restrictedUsers = uids.map((uid, index) => ({
				uid,
				settings: settings[index] || {},
			})).filter(({ settings: userSettings }) => {
				if (Object.prototype.hasOwnProperty.call(userSettings, 'chatAllowList')) {
					return false;
				}
				const oldSetting = userSettings.restrictChat || userSettings.restrictChat === 0 ?
					userSettings.restrictChat : defaultRestrictChat;
				return parseInt(oldSetting, 10) === 1;
			});
			const following = await db.getSortedSetsMembers(restrictedUsers.flatMap(({ uid }) => [
				`following:${uid}`, `followingRemote:${uid}`,
			]));
			const updates = restrictedUsers.map(({ uid, settings: userSettings }, index) => {
				const offset = index * 2;
				const allowedUids = [...following[offset], ...following[offset + 1]].map(String);
				const changes = { chatAllowList: JSON.stringify(allowedUids) };
				// An empty allow list permits everyone, so preserve the old no-followers restriction.
				if (!allowedUids.length && !Object.prototype.hasOwnProperty.call(userSettings, 'disableIncomingMessages')) {
					changes.disableIncomingMessages = 1;
				}
				return [`user:${uid}:settings`, changes];
			});
			await db.setObjectBulk(updates);
			progress.incr(uids.length);
		}, {
			batch: 500,
			progress,
		});
	},
};

	it('should migrate restricted chats to allow lists without overwriting them on rerun', async () => {
		const migration = require('../src/upgrades/4.3.0/chat_allow_list');
		const uids = ['902001', '902002', '902003', '902004', '902005'];
		const previousDefault = await db.getObjectField('config', 'restrictChat');
		const progress = { total: 0, incr: () => {} };

		try {
			await db.setObjectField('config', 'restrictChat', 1);
			await db.sortedSetAddBulk(uids.map((uid, index) => ['users:joindate', index, uid]));
			await db.setObjectBulk([
				[`user:${uids[0]}:settings`, { restrictChat: 1 }],
				[`user:${uids[1]}:settings`, { restrictChat: 1 }],
				[`user:${uids[2]}:settings`, { restrictChat: 0 }],
				[`user:${uids[3]}:settings`, { restrictChat: 1, chatAllowList: '["77"]' }],
			]);
			await db.sortedSetAddBulk([
				[`following:${uids[0]}`, 1, '42'],
				[`following:${uids[0]}`, 2, '43'],
				[`followingRemote:${uids[0]}`, 3, 'https://remote.example/users/44'],
				[`following:${uids[4]}`, 1, '99'],
			]);

			await migration.method.call({ progress });
			assert.deepStrictEqual(JSON.parse(await db.getObjectField(`user:${uids[0]}:settings`, 'chatAllowList')), [
				'42', '43', 'https://remote.example/users/44',
			]);
			assert.deepStrictEqual(JSON.parse(await db.getObjectField(`user:${uids[1]}:settings`, 'chatAllowList')), []);
			assert.strictEqual(Number(await db.getObjectField(`user:${uids[1]}:settings`, 'disableIncomingMessages')), 1);
			assert.strictEqual(await db.getObjectField(`user:${uids[2]}:settings`, 'chatAllowList'), null);
			assert.strictEqual(await db.getObjectField(`user:${uids[3]}:settings`, 'chatAllowList'), '["77"]');
			assert.deepStrictEqual(JSON.parse(await db.getObjectField(`user:${uids[4]}:settings`, 'chatAllowList')), ['99']);

			await db.sortedSetAdd(`following:${uids[0]}`, 3, '44');
			await migration.method.call({ progress });
			assert.deepStrictEqual(JSON.parse(await db.getObjectField(`user:${uids[0]}:settings`, 'chatAllowList')), [
				'42', '43', 'https://remote.example/users/44',
			]);
			assert.strictEqual(Number(await db.getObjectField(`user:${uids[1]}:settings`, 'disableIncomingMessages')), 1);
		} finally {
			if (previousDefault === null) {
				await db.deleteObjectField('config', 'restrictChat');
			} else {
				await db.setObjectField('config', 'restrictChat', previousDefault);
			}
			await db.sortedSetRemove('users:joindate', uids);
			await db.deleteAll(uids.flatMap(uid => [
				`user:${uid}:settings`, `following:${uid}`, `followingRemote:${uid}`,
			]));
		}
	});
